class BankAccount:
    # static variables
    total_accounts = 0
    accounts = []

    def __init__(self, account_holder, password):
        BankAccount.total_accounts += 1
        self._account_number = BankAccount.total_accounts
        self._account_holder = account_holder
        self._balance = 0
        self._password = password

        # add account to class-level accounts list
        BankAccount.accounts.append(self)

    def deposit(self, amount, password):
        if self._password != password:
            print("Authentication failed")
            return
        if amount > 0:
            self._balance += amount
        else:
            print("Invalid deposit amount")

    def withdraw(self, amount, password):
        if self._password != password:
            print("Authentication failed")
            return
        if amount > 0:
            if self._balance >= amount:
                self._balance -= amount
            else:
                print("Insufficient balance")
        else:
            print("Invalid withdrawal amount")

    def check_balance(self):
        return self._balance

    def get_account_holder(self):
        return self._account_holder

    @staticmethod
    def display_all_accounts():
        for account in BankAccount.accounts:
            print("Account Number:", account._account_number)
            print("Account Holder:", account.get_account_holder())
